/* VEXA interactive design prototype. Framework-free, hash-routed, no network requests.
 * Demo checkout never asks for a card or sends personal information.
 * Only validated, non-personal basket identifiers are stored locally.
 */
(() => {
  'use strict';
  const D = window.VEXA;
  const $ = (s, root = document) => root.querySelector(s);
  const $$ = (s, root = document) => [...root.querySelectorAll(s)];
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const asset = name => window.VEXA_ASSETS?.[name + '.jpg'] || 'assets/' + name + '.jpg';
  const money = cents => new Intl.NumberFormat(D.locale,{style:'currency',currency:D.currency,maximumFractionDigits:cents % 100 ? 2 : 0}).format(cents/100);
  const product = id => D.products.find(p => p.id === id);
  const totalStock = p => Object.values(p.stock).reduce((a,b) => a+b,0);
  const icons = {
    arrow:'<path d="M4 12h15M13 5l7 7-7 7"/>', diagonal:'<path d="M5 19L19 5M5 5h14v14"/>',
    search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',
    bag:'<path d="M5 7h14l1 14H4L5 7Z"/><path d="M8 8V6a4 4 0 0 1 8 0v2"/>',
    user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',
    menu:'<path d="M3 7h18M3 12h18M3 17h18"/>',close:'<path d="m5 5 14 14M5 19 19 5"/>',
    plus:'<path d="M5 12h14M12 5v14"/>', minus:'<path d="M5 12h14"/>',
    check:'<path d="m5 12 4 4L19 6"/>',filter:'<path d="M3 7h18M3 17h18"/><circle cx="8" cy="7" r="2" fill="currentColor"/><circle cx="16" cy="17" r="2" fill="currentColor"/>',
    zoom:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6M7 10h6M10 7v6"/>',
    lock:'<rect x="5" y="10" width="14" height="11" rx="1"/><path d="M8 10V6a4 4 0 0 1 8 0v4"/>',
    info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7v1"/>',
    chevron:'<path d="m9 5 7 7-7 7"/>',back:'<path d="M20 12H5m7-7-7 7 7 7"/>'
  };
  const icon = (name,size=18) => `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.45" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name] || icons.arrow}</svg>`;
  const storageKey = 'vexa-prototype-bag-v1';
  function cleanBag(raw){
    if(!Array.isArray(raw)) return [];
    const cleaned = [];
    for(const line of raw.slice(0,100)){
      const p = line && product(line.id);
      if(!p || !p.sizes.includes(line.size) || !p.colours.some(c=>c.name===line.colour) || !Number.isInteger(line.qty) || line.qty<1) continue;
      const max=p.stock[line.size] || 0;
      if(!max) continue;
      const existing=cleaned.find(v=>v.id===p.id&&v.size===line.size&&v.colour===line.colour);
      if(existing) existing.qty=Math.min(max,existing.qty+line.qty);
      else cleaned.push({id:p.id,size:line.size,colour:line.colour,qty:Math.min(line.qty,max)});
    }
    return cleaned;
  }
  function loadBag(){try{return cleanBag(JSON.parse(localStorage.getItem(storageKey) || '[]'));}catch{return [];}}
  const state={bag:loadBag(),pid:'',colour:'',size:'',view:0,modal:'',returnFocus:null,toastTimer:0,order:null,checkoutStep:1,checkoutValid:false,details:{email:'',firstName:'',lastName:'',address:'',apartment:'',city:'',postal:'',country:'United Kingdom'},shipping:'standard',payment:'approved',unit:'cm',busy:false};
  function saveBag(){try{localStorage.setItem(storageKey,JSON.stringify(state.bag));}catch{/* Session-only basket fallback when storage is unavailable. */}}
  function bagCount(){return state.bag.reduce((n,l)=>n+l.qty,0);}
  function subtotal(){return state.bag.reduce((n,l)=>n+product(l.id).price*l.qty,0);}
  const shippingChoice = () => D.shipping.find(s=>s.id===state.shipping)||D.shipping[0];
  function route(){const u=new URL(location.hash.startsWith('#/')?location.hash.slice(1):'/', 'https://vexa.local');return {path:u.pathname,params:u.searchParams};}
  function go(path){if(location.hash==='#'+path) render();else location.hash=path;}
  function notify(message){const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>t.classList.remove('show'),3800);}
  function logo(){return '<span class="wordmark">VEXA</span>';}
  function header(){
    const r=route().path;
    $('#site-header').innerHTML=`<nav class="site-nav" aria-label="Main navigation"><button class="icon-button mobile-menu" data-action="menu" aria-label="Open navigation">${icon('menu',22)}</button><a class="wordmark" href="#/" aria-label="VEXA home">VEXA</a><div class="nav-links"><a href="#/shop" class="${r==='/shop'?'active':''}">Shop</a><a href="#/shop?new=1">New arrivals</a><a href="#/lookbook" class="${r==='/lookbook'?'active':''}">Collections</a><a href="#/about" class="${r==='/about'?'active':''}">About</a></div><div class="nav-actions"><button data-action="search" aria-label="Search the collection">${icon('search',19)}<span class="action-label">Search</span></button><button class="account-button" data-action="account" aria-label="Account information">${icon('user',18)}<span class="action-label">Account</span></button><button data-action="bag" aria-label="Open shopping bag, ${bagCount()} item${bagCount()===1?'':'s'}">${icon('bag',18)}<span class="action-label">Bag</span><span class="bag-count">(${bagCount()})</span></button></div></nav>`;
  }
  function footer(compact=false){
    $('#site-footer').innerHTML=compact?`<div class="compact-footer"><span>VEXA / DEMO CHECKOUT</span><a href="#/guide">No real orders, payments or emails.</a></div>`:`<section class="newsletter wrap" aria-labelledby="newsletter-heading"><div><h2 id="newsletter-heading">Stay in the loop.</h2><p class="newsletter-caption">Collection notes. New perspectives. No noise.</p></div><form class="newsletter-form" id="newsletter-form" novalidate><label class="sr-only" for="newsletter-email">Email address</label><div class="newsletter-input"><input id="newsletter-email" name="email" type="email" autocomplete="email" placeholder="Your email address" aria-describedby="newsletter-note" required><button type="submit" aria-label="Try demo newsletter sign-up">${icon('arrow',22)}</button></div><p class="form-error" id="newsletter-note">Demo sign-up only. No email will be sent or stored.</p></form></section><div class="footer-main wrap"><div class="footer-grid"><div class="footer-brand"><a href="#/" aria-label="VEXA home">${logo()}</a><p>CULTURE. FORM. PERSPECTIVE.<br>A DIFFERENT KIND OF UNIFORM.</p></div><div class="footer-column"><h3>Explore</h3><a href="#/shop">Shop all</a><a href="#/shop?new=1">New arrivals</a><a href="#/lookbook">Collections</a><a href="#/about">The studio</a></div><div class="footer-column"><h3>Client services</h3><a href="#/support/shipping">Shipping</a><a href="#/support/returns">Returns</a><a href="#/support/sizing">Size & fit</a><a href="#/support/contact">Contact</a></div><div class="footer-column"><h3>The details</h3><a href="#/support/privacy">Privacy</a><a href="#/support/terms">Terms</a><a href="#/design-system">Design system</a><a href="#/guide">Prototype guide</a></div></div><div class="footer-base"><span>© 2026 VEXA CONCEPT / ALL PRODUCTS & PRICES ARE ILLUSTRATIVE.</span><span>GBP / £ <span aria-hidden="true">&nbsp; · &nbsp;</span><a href="#/guide">Concept imagery · Not a live store</a></span></div></div>`;
  }
  function card(p,i=0){
    return `<article class="product-card"><div class="product-media-wrap"><a class="product-card-media" href="#/product/${p.id}" aria-label="View ${esc(p.name)}"><span class="product-index">${String(i+1).padStart(2,'0')} / ${esc(p.collection.toUpperCase())}</span><img src="${asset(p.image)}" alt="${esc(p.name)} concept product image" loading="lazy" width="700" height="800">${!totalStock(p)?'<span class="badge">Unavailable · demo</span>':''}</a><button class="quick-view" data-action="quick-view" data-id="${p.id}" aria-label="Choose options for ${esc(p.name)}">${icon('plus',17)}</button></div><div class="product-card-info"><a href="#/product/${p.id}">${esc(p.name)}</a><span class="price">${money(p.price)}</span></div><div class="product-card-sub"><span>${esc(p.colours[0].name)}</span><span class="mini-swatches" aria-label="${p.colours.length} colour option${p.colours.length===1?'':'s'}">${p.colours.map(c=>`<span class="mini-swatch" style="--swatch:${c.hex}"></span>`).join('')}</span></div></article>`;
  }
  function home(){return `<section class="hero" aria-labelledby="hero-title"><div class="hero-copy"><div class="hero-kicker eyebrow"><span class="tiny-square"></span> COLLECTION 001 <span>THE EVERYDAY UNIFORM</span></div><h1 id="hero-title"><span>BUILT</span><span>DIFFERENT.</span></h1><p class="hero-description">Heavyweight essentials.<br>For a world that doesn't stand still.</p><a class="btn accent" href="#/shop?new=1">Shop the drop ${icon('arrow',20)}</a><div class="hero-bottom"><span>01 / FOUNDATION</span><span class="line"></span><span>CULTURE IN EVERY THREAD.</span></div></div><div class="hero-photo"><img src="${asset('campaign-front')}" alt="VEXA concept campaign: a model in dark streetwear against concrete architecture" fetchpriority="high" width="1500" height="1236"><span class="image-caption">CITY ROOTS.<br>A DIFFERENT PERSPECTIVE.</span></div></section><div class="marquee-strip"><span>VEXA STUDIO <span aria-hidden="true">+</span> FORM WITHOUT COMPROMISE</span><span>AN INDEPENDENT POINT OF VIEW <span aria-hidden="true">↗</span></span><span>COLLECTION / 001</span></div><section class="section wrap"><div class="section-heading"><div><p class="eyebrow muted">THE CURRENT EDIT</p><h2>New arrivals.</h2></div><a class="text-link" href="#/shop?new=1">View the collection ${icon('arrow',18)}</a></div><div class="product-grid">${D.products.slice(0,4).map(card).join('')}</div><p class="price-note">ILLUSTRATIVE GBP PRICING / CONCEPT PRODUCT IMAGERY</p></section><section class="editorial-block"><div class="editorial-image"><img src="${asset('campaign-back')}" alt="VEXA campaign styling reference showing an oversized jacket in a city setting" loading="lazy" width="1500" height="615"><span class="image-caption">STUDIO NOTES / 001</span></div><div class="editorial-content"><p class="eyebrow muted">BEYOND THE LOGO</p><h2>A higher<br>standard.</h2><p>An everyday uniform, with a point of view. Familiar forms. Considered proportions. Space to make it your own.</p><a class="text-link" href="#/about">Inside VEXA ${icon('diagonal',17)}</a></div></section><section class="section wrap"><div class="section-heading"><div><p class="eyebrow muted">BUILD YOUR UNIFORM</p><h2>Find your form.</h2></div></div><div class="category-list">${[['01','T-Shirts','T-Shirts'],['02','Hoodies & layers','Hoodies'],['03','Trousers','Trousers'],['04','Outerwear','Outerwear'],['05','Accessories','Accessories']].map(([n,t,c])=>`<a class="category-row" href="#/shop?category=${encodeURIComponent(c)}"><div class="row-main"><span class="eyebrow">${n}</span><h3>${t}</h3></div><span class="row-count">${D.products.filter(p=>p.category===c).length} STYLES</span>${icon('diagonal',22)}</a>`).join('')}</div></section>`;}
  function filtered(params){
    let list=D.products.filter(p=>(!params.get('category')||p.category===params.get('category'))&&(!params.get('new')||p.new)&&(!params.get('collection')||p.collection===params.get('collection'))&&(!params.get('q')||(p.name+' '+p.category+' '+p.collection+' '+p.colours.map(c=>c.name).join(' ')).toLowerCase().includes(params.get('q').trim().toLowerCase()))&&(!params.get('size')||p.sizes.includes(params.get('size')))&&(!params.get('colour')||p.colours.some(c=>c.name===params.get('colour')))&&(!params.get('available')||(params.get('size')?p.stock[params.get('size')]>0:totalStock(p)>0))&&(!params.get('max')||p.price<=Number(params.get('max'))*100));
    if(params.get('empty'))list=[];
    const sort=params.get('sort');
    if(sort==='low')list.sort((a,b)=>a.price-b.price);
    if(sort==='high')list.sort((a,b)=>b.price-a.price);
    if(sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name));
    return list;
  }
  function shop(){
    const {params}=route(),list=filtered(params),search=params.get('q'),title=search?'Search results.':params.get('category')?params.get('category')+'.':params.get('collection')?params.get('collection')+'.':params.get('new')?'The new edit.':'The collection.';
    const active=[...params.entries()].filter(([k])=>['size','colour','max','available','collection','q','new','empty'].includes(k));
    return `<section class="page-top wrap"><div class="breadcrumbs"><a href="#/">Home</a><span>/</span><span>${search?'Search':'Shop'}</span></div><div class="title-row"><div><p class="eyebrow muted" style="margin-bottom:17px">VEXA / COLLECTION 001</p><h1>${esc(title)}</h1></div><p>${search?`Showing matches for “${esc(search)}”.`:'Considered pieces. Uncomplicated choices.<br>Build your everyday uniform.'}</p></div></section><section class="wrap shop-products" aria-label="Product collection"><nav class="category-tabs" aria-label="Product categories">${['All','T-Shirts','Hoodies','Trousers','Outerwear','Accessories'].map(c=>`<a href="#/shop${c==='All'?'':'?category='+encodeURIComponent(c)}" class="${(params.get('category')||'All')===c?'active':''}">${c}</a>`).join('')}</nav><div class="shop-toolbar"><div class="toolbar-left"><button class="filter-button" data-action="filters">${icon('filter',17)}Filters ${active.length?`(${active.length})`:''}</button><span class="count-note" aria-live="polite">${list.length} ${list.length===1?'STYLE':'STYLES'}</span></div><div class="toolbar-right"><div class="sort-control"><label for="sort">Sort by</label><select id="sort" aria-label="Sort products"><option value="featured" ${!params.get('sort')?'selected':''}>Featured</option><option value="low" ${params.get('sort')==='low'?'selected':''}>Price: low to high</option><option value="high" ${params.get('sort')==='high'?'selected':''}>Price: high to low</option><option value="name" ${params.get('sort')==='name'?'selected':''}>Name: A to Z</option></select></div></div></div>${active.length?`<div class="active-filters">${active.map(([k,v])=>`<button class="filter-chip" data-action="clear-filter" data-key="${k}" aria-label="Remove ${esc(k)} filter">${esc(k==='available'?'Available':k==='max'?'Under '+money(Number(v)*100):k==='new'?'New arrivals':k==='empty'?'Empty-state demo':v)} ${icon('close',12)}</button>`).join('')}<button class="clear-filters" data-action="clear-all">Clear all</button></div>`:''}${list.length?`<div class="product-grid">${list.map(card).join('')}</div><p class="price-note">ALL PRICES, AVAILABILITY AND PRODUCT SPECIFICATIONS ARE DESIGN FIXTURES.</p>`:empty('Nothing here. Yet.','Try a different search or remove a filter to explore the collection.','Clear filters','#/shop','search')}</section>`;
  }
  function empty(title,copy,cta='#',url='#/shop',sym='bag'){return `<div class="empty-state">${icon(sym,32)}<h2>${title}</h2><p>${copy}</p><a class="btn" href="${url}">${cta}${icon('arrow',17)}</a></div>`;}
  function pdp(){
    const id=route().path.split('/')[2],p=product(id);if(!p)return notFound();
    if(state.pid!==id){state.pid=id;state.colour=p.colours[0].name;state.size=p.sizes.length===1&&totalStock(p)?p.sizes[0]:'';state.view=0;}
    const c=p.colours.find(v=>v.name===state.colour)||p.colours[0];
    return `<div class="wrap"><div class="breadcrumbs product-breadcrumb"><a href="#/">Home</a><span>/</span><a href="#/shop?category=${encodeURIComponent(p.category)}">${p.category}</a><span>/</span><span>${p.name}</span></div><div class="product-layout"><section class="gallery" aria-label="Product photographs"><button class="gallery-main" data-action="zoom" data-view="${state.view}" aria-label="Enlarge ${esc(p.name)} concept image"><span class="photo-label">${['01 / FRONT VIEW','02 / DETAIL CROP','03 / CONSTRUCTION CROP'][state.view]}</span><img id="main-product-image" src="${asset(c.image)}" alt="${esc(p.name)} in ${esc(c.name)}, illustrative ${['front view','detail crop','construction crop'][state.view]}" width="700" height="756"><span class="zoom-label">${icon('zoom',20)}</span></button><div class="gallery-thumbs" aria-label="Choose an image">${[0,1,2].map(i=>`<button class="gallery-thumb ${state.view===i?'active':''}" data-action="gallery" data-view="${i}" aria-label="${['Front view','Detail crop','Construction crop'][i]}" aria-pressed="${state.view===i}"><img src="${asset(c.image)}" alt="" width="70" height="78"></button>`).join('')}</div><p class="asset-note">CONCEPT IMAGERY / Detail views are crops, not additional photographs. Colour variants are illustrative. Final production photography is required.</p></section><section class="product-details" aria-labelledby="product-name"><p class="eyebrow muted">${p.tag}</p><h1 id="product-name">${p.name}</h1><p class="product-price">${money(p.price)} <span class="sr-only">Illustrative price</span></p><p class="product-intro">${p.description}</p><div class="option-label"><div>Colour <span>/ ${c.name}</span></div><span>${p.colours.length} ${p.colours.length===1?'colour':'colours'}</span></div><div class="swatches" role="group" aria-label="Choose a colour">${p.colours.map(col=>`<button class="swatch-button" data-action="colour" data-colour="${esc(col.name)}" aria-label="${esc(col.name)}" aria-pressed="${col.name===c.name}" style="--swatch:${col.hex}"><span></span></button>`).join('')}</div><div id="size-section"><div class="option-label"><div>Size <span id="size-selected-label">${state.size?'/ '+state.size:''}</span></div><button data-action="size-guide">Size guide ${iconInline()}</button></div><div class="size-grid" role="group" aria-label="Choose a size" aria-describedby="product-error">${p.sizes.map(s=>`<button class="size-button" data-action="size" data-size="${esc(s)}" aria-label="Size ${esc(s)}${!p.stock[s]?', unavailable in demo':''}" aria-pressed="${state.size===s}" ${!p.stock[s]?'disabled':''}>${s}</button>`).join('')}</div><p class="form-error product-error" id="product-error" role="alert"></p></div><div class="purchase-area"><button class="btn full accent" id="add-button" data-action="add" ${!totalStock(p)?'disabled':''}>${!totalStock(p)?'Unavailable in this demo':'Add to bag'} ${icon('plus',17)}</button></div>${!totalStock(p)?'<button class="text-link" data-action="notify-stock">Preview availability request</button>':''}<p class="availability-note">ILLUSTRATIVE PRICE / SAMPLE AVAILABILITY<br>Sample delivery costs are shown before demo confirmation.</p><div class="product-detail-rows"><details><summary>The details</summary><div>${p.material}<br>All product specifications are fictional design content.</div></details><details><summary>Size & fit</summary><div>${p.fit}<br><button class="text-link" data-action="size-guide">Open sample measurements</button></div></details><details><summary>Materials & care</summary><div>Care instructions must be supplied from the approved garment label before launch. This prototype does not make verified material or care claims.</div></details><details><summary>Shipping & returns</summary><div>Demonstration shipping: ${money(D.shipping[0].price)} standard or ${money(D.shipping[1].price)} express. Timings and charges are fictional fixtures, not a service promise.<br><a href="#/support/returns">Read the policy placeholder</a></div></details></div></section></div></div><section class="section wrap related-section"><div class="section-heading"><div><p class="eyebrow muted">FINISH THE UNIFORM</p><h2>In good company.</h2></div><a class="text-link" href="#/shop">Shop all ${icon('arrow',17)}</a></div><div class="product-grid">${D.products.filter(v=>v.id!==p.id).slice(0,4).map(card).join('')}</div></section><div class="mobile-purchase"><div><strong>${money(p.price)}</strong><small id="mobile-size-label">${state.size?'Size '+state.size:'Select a size'}</small></div><button class="btn accent" data-action="add" ${!totalStock(p)?'disabled':''}>${!totalStock(p)?'Unavailable':'Add to bag'}${icon('plus',16)}</button></div>`;
  }
  function iconInline(){return '<span aria-hidden="true">↗</span>';}
  function bagLine(l,i,compact=false){const p=product(l.id),c=p.colours.find(c=>c.name===l.colour);return `<article class="bag-line ${compact?'compact':''}"><a href="#/product/${p.id}" data-action="close-link"><img src="${asset(c.image)}" alt="${esc(p.name)}, ${esc(l.colour)}" width="102" height="120"></a><div><a class="bag-line-title" href="#/product/${p.id}" data-action="close-link">${p.name}</a><p class="bag-line-meta">${l.colour}<br>Size ${l.size}</p><div class="quantity-row"><div class="quantity-control" aria-label="Quantity for ${p.name}"><button data-action="qty" data-index="${i}" data-delta="-1" aria-label="Decrease ${p.name} quantity" ${l.qty===1?'disabled':''}>${icon('minus',12)}</button><span aria-live="polite">${l.qty}</span><button data-action="qty" data-index="${i}" data-delta="1" aria-label="Increase ${p.name} quantity" ${l.qty>=p.stock[l.size]?'disabled':''}>${icon('plus',12)}</button></div><button class="remove-item" data-action="remove" data-index="${i}" aria-label="Remove ${p.name} from bag">Remove</button></div></div><span class="bag-line-price">${money(p.price*l.qty)}</span></article>`;}
  function summaryProducts(lines=state.bag){return lines.map(l=>{const p=product(l.id);return `<div class="summary-product"><img src="${asset(p.colours.find(c=>c.name===l.colour).image)}" alt="" width="62" height="74"><div class="summary-info"><strong>${p.name}</strong><small>${l.colour} / ${l.size} / Qty ${l.qty}</small></div><span class="price">${money(p.price*l.qty)}</span></div>`;}).join('');}
  function orderSummary(checkout=false){return `<aside class="order-summary" aria-label="Order summary"><h2>Order summary${checkout?` (${bagCount()})`:''}</h2>${checkout?summaryProducts():''}<div class="summary-row"><span>Subtotal</span><span>${money(subtotal())}</span></div><div class="summary-row"><span>Delivery</span><span>${checkout?money(shippingChoice().price):'Calculated at checkout'}</span></div><div class="summary-row"><span>Demo taxes</span><span>Included in sample prices</span></div><div class="summary-row total"><span>${checkout?'Total':'Subtotal'}</span><span>${money(subtotal()+(checkout?shippingChoice().price:0))}</span></div><p class="summary-note">${checkout?'Final sample total shown before confirmation. No real tax calculation, charge or order is created.':'Delivery is added at checkout. Prices and taxes are illustrative, not a real commercial offer.'}</p>${!checkout?`<a class="btn full" href="#/checkout">Continue to checkout ${icon('arrow',17)}</a><p class="summary-note" style="margin-bottom:0">Guest checkout. Demo only.</p>`:''}</aside>`;}
  function bag(){return `<section class="page-top wrap"><div class="breadcrumbs"><a href="#/">Home</a><span>/</span><span>Shopping bag</span></div><div class="title-row"><h1>Your bag<span class="muted"> (${bagCount()})</span>.</h1><p>A few considered choices.<br>Make them your own.</p></div></section><section class="wrap">${state.bag.length?`<div class="bag-layout"><div><div class="bag-list">${state.bag.map((l,i)=>bagLine(l,i)).join('')}</div><a class="text-link" href="#/shop" style="margin-top:24px">${icon('back',16)} Continue exploring</a></div>${orderSummary()}</div>`:empty('Room for something different.','Your bag is empty. Start with the pieces that speak to you.','Explore the collection')}</section>`;}
  function field(name,label,opts={}){const v=state.details[name]||'';return `<div class="field ${opts.full?'full':''}"><label for="${name}">${label}${opts.optional?' <span class="muted">(optional)</span>':''}</label>${opts.select?`<select id="${name}" name="${name}" autocomplete="country-name">${['United Kingdom','Nigeria','United States','Canada','Other'].map(s=>`<option ${v===s?'selected':''}>${s}</option>`).join('')}</select>`:`<input id="${name}" name="${name}" value="${esc(v)}" type="${opts.type||'text'}" autocomplete="${opts.auto||'off'}" ${!opts.optional?'required':''} maxlength="${name==='email'?254:160}" aria-describedby="${name}-error">`}<span id="${name}-error" class="form-error"></span></div>`;}
  function addressPreview(){const d=state.details;return `<div class="address-preview"><strong>${esc(d.firstName)} ${esc(d.lastName)}</strong>${esc(d.address)}${d.apartment?'<br>'+esc(d.apartment):''}<br>${esc(d.city)}, ${esc(d.postal)}<br>${esc(d.country)}<br><span class="muted">${esc(d.email)}</span></div>`;}
  function checkout(){
    if(!state.bag.length)return `<section class="wrap">${empty('Nothing to check out.','Add a piece to your bag before exploring the demo checkout.','Explore the collection')}</section>`;
    let content='';
    if(state.checkoutStep===1)content=`<form id="checkout-details" novalidate><div class="form-section-head"><h2>Contact details</h2><button type="button" data-action="sample-details">Use sample details</button></div><div class="form-grid">${field('email','Email address',{full:true,type:'email',auto:'email'})}</div><div class="form-section-head"><h2>Delivery address</h2></div><div class="form-grid">${field('firstName','First name',{auto:'given-name'})}${field('lastName','Last name',{auto:'family-name'})}${field('address','Address',{full:true,auto:'address-line1'})}${field('apartment','Apartment, suite, etc.',{full:true,optional:true,auto:'address-line2'})}${field('city','City',{auto:'address-level2'})}${field('postal','Postcode / ZIP',{auto:'postal-code'})}${field('country','Country / region',{full:true,select:true})}</div><p class="field-note">Use sample details for this demo. Entries stay in memory on this page, are not transmitted and are not saved after refresh.</p><div class="checkout-actions"><a class="checkout-back" href="#/bag">Back to bag</a><button class="btn" type="submit">Continue to delivery ${icon('arrow',17)}</button></div></form>`;
    if(state.checkoutStep===2)content=`<h2 style="font-size:28px">How should it arrive?</h2>${addressPreview()}<form id="shipping-form"><div class="shipping-options">${D.shipping.map(s=>`<label class="radio-option"><input type="radio" name="shipping" value="${s.id}" ${state.shipping===s.id?'checked':''}><span class="radio-copy"><strong>${s.name}</strong><small>${s.note}</small></span><span class="price">${money(s.price)}</span></label>`).join('')}</div><p class="field-note">Delivery fees and estimates are fictional. All destination choices use the same sample fees in this prototype.</p><div class="checkout-actions"><button type="button" class="checkout-back" data-action="checkout-step" data-step="1">Back to details</button><button class="btn" type="submit">Review & payment ${icon('arrow',17)}</button></div></form>`;
    if(state.checkoutStep===3)content=`<h2 style="font-size:28px">One final look.</h2><p class="field-note" style="margin-bottom:0">Review your sample delivery details and final total.</p>${addressPreview()}<div class="summary-row"><span>${shippingChoice().name} · demo</span><span>${money(shippingChoice().price)}</span></div><div class="demo-callout">${icon('info',20)}<span><strong>This is a payment simulation.</strong><br>No card details are requested. No payment, order or confirmation email will be sent.</span></div><form id="payment-form"><div class="shipping-options"><label class="radio-option"><input type="radio" name="payment" value="approved" ${state.payment==='approved'?'checked':''}><span class="radio-copy"><strong>Simulate successful payment</strong><small>Continue to the demo confirmation screen.</small></span></label><label class="radio-option"><input type="radio" name="payment" value="declined" ${state.payment==='declined'?'checked':''}><span class="radio-copy"><strong>Simulate declined payment</strong><small>Preview recovery without losing the bag or details.</small></span></label></div><p id="payment-error" role="alert" hidden></p><div class="checkout-actions"><button class="checkout-back" type="button" data-action="checkout-step" data-step="2">Back to delivery</button><button class="btn accent" id="payment-button" type="submit">Place demo order · ${money(subtotal()+shippingChoice().price)} ${icon('arrow',17)}</button></div></form>`;
    return `<section class="wrap checkout-wrap"><div class="checkout-head"><h1>Checkout.</h1><span>${icon('lock',15)} DEMO / NO REAL PAYMENT</span></div><div class="checkout-layout"><div><nav class="stepper" aria-label="Checkout progress">${['Details','Delivery','Payment'].map((s,i)=>`<button data-action="checkout-step" data-step="${i+1}" class="${state.checkoutStep===i+1?'active':''}" ${i+1>state.checkoutStep?'disabled':''} ${state.checkoutStep===i+1?'aria-current="step"':''}><span class="step-number">${i+1<state.checkoutStep?'✓':String(i+1).padStart(2,'0')}</span>${s}</button>`).join('')}</nav>${content}</div>${orderSummary(true)}</div></section>`;
  }
  function confirmation(){
    const o=state.order;
    if(!o)return `<section class="wrap">${empty('No demo order to show.','Complete the simulated checkout to see the confirmation state. Demo order details are cleared when this page is refreshed.','Explore the collection','#/shop','check')}</section>`;
    return `<section class="confirmation wrap"><div class="confirmation-mark">${icon('check',34)}</div><p class="eyebrow muted">DEMO JOURNEY COMPLETE</p><h1>Consider it yours.<br><span class="muted">In the prototype.</span></h1><p class="confirmation-intro">Your demo order has been confirmed. No purchase was made, no payment was taken and no email was sent.</p><div class="receipt"><div class="receipt-top"><span>${o.ref}</span><span>${o.date}</span></div>${summaryProducts(o.lines)}<div class="summary-row"><span>Subtotal</span><span>${money(o.subtotal)}</span></div><div class="summary-row"><span>${o.shippingName} · sample</span><span>${money(o.shippingPrice)}</span></div><div class="summary-row total"><span>Total · demo</span><span>${money(o.total)}</span></div><p class="summary-note">This is a prototype receipt, not proof of a purchase. Sample taxes are included in the illustrative prices.</p></div><div class="actions" style="justify-content:center"><a class="btn" href="#/shop">Continue exploring ${icon('arrow',18)}</a><a class="btn secondary" href="#/guide">Review the prototype</a></div></section>`;
  }
  function about(){return `<section class="brand-intro wrap"><div><p class="eyebrow muted">THE VEXA POINT OF VIEW</p><h1>Not another<br>uniform.</h1></div><div class="brand-copy"><p>VEXA is a study in contrast. The familiar and the unexpected. Street-level energy and a considered silhouette.</p><p>Our concept starts with the clothes you reach for every day, then asks what they could become. A heavier drape. A different proportion. A little more intention.</p><a class="text-link" href="#/shop">Explore the collection ${icon('arrow',17)}</a></div></section><section class="brand-photo"><img src="${asset('campaign-back')}" alt="VEXA editorial campaign concept in a concrete cityscape"><span class="image-caption">AN INDEPENDENT POINT OF VIEW / CONCEPT CAMPAIGN</span></section><section class="section wrap brand-values">${[['01','Culture first.','A visual language shaped by the street, personal expression and everyday movement.'],['02','Form matters.','Clean silhouettes. Deliberate proportions. An identity that does not rely on decoration.'],['03','Make it yours.','The collection is a starting point. The way you wear it is entirely your own.']].map(([n,t,p])=>`<div class="brand-value"><p class="eyebrow muted">${n} / STUDIO PRINCIPLE</p><h2>${t}</h2><p>${p}</p></div>`).join('')}</section>`;}
  function lookbook(){return `<section class="page-top wrap"><div class="breadcrumbs"><a href="#/">Home</a><span>/</span><span>Collections</span></div><div class="title-row"><div><p class="eyebrow muted" style="margin-bottom:16px">THE VISUAL JOURNAL</p><h1>In our element.</h1></div><p>Collection 001.<br>A different perspective on the everyday.</p></div></section><section class="lookbook-grid wrap"><article class="lookbook-feature"><div class="look-photo"><img src="${asset('campaign-front')}" alt="Foundation editorial styling concept" width="1500" height="1236"><span class="image-caption">001 / FOUNDATION</span></div><div class="look-caption"><div><h2>The everyday edit.</h2><p>FOUNDATION / LAYERS & PROPORTION</p></div><a class="text-link" href="#/shop?collection=Foundation">Shop the edit ${icon('diagonal',17)}</a></div><p class="asset-note">Editorial styling reference, not a photograph of every linked garment.</p></article><article class="lookbook-feature"><div class="look-photo"><img src="${asset('campaign-back')}" alt="Archive editorial styling concept" width="1500" height="615"><span class="image-caption">002 / ARCHIVE</span></div><div class="look-caption"><div><h2>A new perspective.</h2><p>ARCHIVE / FORM & TEXTURE</p></div><a class="text-link" href="#/shop?collection=Archive">Shop the edit ${icon('diagonal',17)}</a></div><p class="asset-note">Concept campaign artwork. Replace with approved, high-resolution photography before launch.</p></article></section>`;}
  const supportContent={
    shipping:['Shipping','This is a design prototype, not a fulfilment service.','The checkout demonstrates two fictional shipping options: standard at £12 and express at £22. Delivery time estimates are sample interface content. No parcel will be dispatched.','Before launch, connect real rates for supported destinations, disclose taxes and duties, and replace all sample timings with approved fulfilment information.'],
    returns:['Returns','A placeholder for the brand’s approved returns policy.','No real returns promise has been made in this prototype. Products, transactions and receipts are fictional.','Before launch, provide the applicable return window, eligibility, costs, contact route and refund process for each market. Policy copy must be reviewed for the actual business and jurisdiction.'],
    privacy:['Privacy','No personal data is sent by this prototype.','The bag stores only product identifiers, colour, size and quantity in browser local storage when available. Checkout details remain in page memory and disappear on refresh. Newsletter entries are validated for the demo but are not submitted or stored.','This is a behaviour explanation, not a production privacy notice. A live store needs a policy reflecting its actual processors, cookies, retention, customer rights and applicable laws.'],
    terms:['Terms','Demonstration only.','VEXA is used here as a working brand name. Products, prices, availability, garment measurements and order confirmations are illustrative. Nothing on this prototype constitutes a real sale or confirms a payment.','Verify brand naming, product content, asset rights, pricing, policies and third-party integrations before publication. The code is an editable UI prototype, not an operational commerce backend.'],
    sizing:['Size & fit','Understand the shape before choosing a size.','Product pages include illustrative size selectors and a sample measurement table. These measurements demonstrate the interface and should not be used to order a real garment.','Final product-specific measurements, fit guidance and measurement instructions must be supplied by the brand.'],
    contact:['Contact','Client services, without the imaginary inbox.','No brand email address, telephone number or social account was supplied. This prototype deliberately does not invent one.','A production contact page should contain the approved support channel, response expectations and accessible contact form. For this demo, use the sample enquiry below to preview its success state.']
  };
  function support(){const key=route().path.split('/')[2],s=supportContent[key];if(!s)return notFound();return `<article class="wrap reading-page"><p class="eyebrow muted">VEXA / CLIENT SERVICES</p><h1>${s[0]}.</h1><h2>${s[1]}</h2><p>${s[2]}</p><p>${s[3]}</p>${key==='sizing'?'<button class="btn" data-action="general-size-guide">View sample size guide</button>':''}${key==='contact'?'<div class="contact-demo"><p>Preview only: no enquiry leaves this page.</p><button class="btn" data-action="sample-enquiry">Try sample enquiry</button></div>':''}<div class="rule"></div><a class="text-link" href="#/shop">Return to the collection ${icon('arrow',17)}</a></article>`;}
  const routeTiles=[['01','Homepage','Campaign, discovery, newsletter.','/'],['02','Collection','Filters, sorting and product cards.','/shop'],['03','Product','Colour, sizes, imagery and options.','/product/foundation-hoodie'],['04','Shopping bag','Quantity, removal and totals.','/bag'],['05','Checkout','Guest details, delivery and demo payment.','/checkout'],['06','Confirmation','Reached after successful simulation.','/confirmation'],['07','Brand story','Identity, editorial and principles.','/about'],['08','Lookbook','Collection storytelling and shopping.','/lookbook'],['09','Design system','Tokens, components and UI states.','/design-system'],['10','Empty results','Clear filters to recover.','/shop?empty=1'],['11','Unavailable product','Sold-out and request states.','/product/studio-cap'],['12','Privacy & policies','Explicit production content placeholders.','/support/privacy']];
  function guide(){return `<section class="wrap section"><p class="eyebrow muted">VEXA / DESIGN HANDOFF 01</p><div class="title-row" style="margin-top:18px"><h1>A working<br>point of view.</h1></div><p class="guide-lead">An editable, responsive front-end prototype. Explore the full shopping journey, review the interface states and use the source files as the design handoff. No live payments, orders, emails or accounts.</p><div class="actions" style="margin-top:28px"><button class="btn" data-action="seed-bag">Load a sample bag ${icon('arrow',17)}</button><a class="btn secondary" href="#/design-system">Explore the design system</a></div><p class="asset-note">Loading the sample bag replaces the demo bag with a hoodie and cargo trousers. It does not place an order.</p><div class="route-map">${routeTiles.map(([n,t,d,h])=>`<a class="route-tile" href="#${h}"><span class="eyebrow muted">${n}</span><h3>${t}</h3><p>${d}</p></a>`).join('')}</div><div class="guide-panel"><h2>The intended journey.</h2><p class="guide-lead">Homepage → Collection → Product → Select colour and size → Add to bag → Review bag → Guest checkout → Delivery → Payment simulation → Confirmation.</p><div class="guide-columns" style="margin-top:28px"><div><h3>Test the edges.</h3><p>Try adding a hoodie without a size. Filter to no results. Select a chalk colourway. Open the bag, change quantity and remove an item. Simulate a declined payment, then approve it without re-entering details.</p></div><div><h3>Designed for both hands.</h3><p>Review at 1440px and 390px. Mobile has its own menu, filter drawer, swipe gestures on product imagery and purchase bar. Keyboard focus, Escape-to-close and reduced-motion preferences are supported.</p></div></div></div><div class="guide-panel"><h2>What is editable.</h2><div class="guide-columns"><div><h3>The actual source</h3><p>src/styles.css holds the tokens and responsive components. src/catalogue.js contains sample product data. src/app.js contains routes and interactions. All interface text, layout and behaviour can be edited directly.</p></div><div><h3>Design exports</h3><p>The package includes individual desktop/mobile screenshots, editable SVG screen snapshots, design tokens and a handoff document. SVGs contain editable text and shapes, but are not native Figma Auto Layout components.</p></div></div></div><div class="guide-panel"><h2>Before this becomes a store.</h2><div class="guide-columns"><div><h3>Real content and assets</h3><p>The campaign and garment images are derived from the generated concept supplied in this conversation. Some crops are low resolution. Replace them with approved original photography, actual garment measurements, validated stock and real prices.</p></div><div><h3>Real commerce and validation</h3><p>Connect a commerce backend, inventory, payment provider, order management, authentication where needed and transactional email. Approve policies and shipping rates. Conduct user research, assistive-technology testing and real-device checks before launch.</p></div></div><p class="asset-note" style="margin-top:30px">This package has not been validated through customer research. Browser checks do not constitute an accessibility certification.</p></div></section>`;}
  function designSystem(){const tokens=[['Paper','#f4f2ed'],['Ink','#171715'],['Surface','#e9e6df'],['Muted','#66655e'],['Accent','#b63823'],['Rule','#cfcbc2']];return `<section class="wrap section"><p class="eyebrow muted">VEXA / SYSTEM 01</p><div class="title-row" style="margin-top:18px"><h1>Made to hold<br>together.</h1></div><p class="guide-lead">A restrained visual system for expressive products and uncomplicated shopping. The interface stays quiet. The clothes take the space.</p><div class="guide-panel"><h2>01 / Colour</h2><div class="token-grid">${tokens.map(([n,c])=>`<div class="token-item"><div class="token-swatch" style="background:${c}"></div><strong>${n}</strong><small>${c.toUpperCase()}</small></div>`).join('')}</div></div><div class="guide-panel"><h2>02 / Type</h2><div class="type-specimen"><div class="spec-label">CAMPAIGN DISPLAY<br>Arial / 900<br>Fluid 66–142px</div><h2 style="font-size:84px;font-weight:900;letter-spacing:-.07em">BUILT DIFFERENT.</h2></div><div class="type-specimen"><div class="spec-label">PAGE HEADING<br>Arial / 800<br>52–76px</div><h2 style="font-size:65px">The collection.</h2></div><div class="type-specimen"><div class="spec-label">BODY / INTERFACE<br>Arial / 400–600<br>12–16px</div><p style="font-size:16px;line-height:1.8;max-width:540px">Considered pieces. Uncomplicated choices. Clear product details, accessible controls and room for the brand to speak.</p></div><div class="type-specimen"><div class="spec-label">UTILITY LABELS<br>Courier New / 400<br>9–11px</div><p class="eyebrow">COLLECTION 001 / THE EVERYDAY UNIFORM</p></div></div><div class="guide-panel"><h2>03 / Action states</h2><div class="component-board"><div class="component-cell"><p>PRIMARY / DEFAULT</p><button class="btn accent" data-action="state-toast">Add to bag ${icon('plus',16)}</button></div><div class="component-cell"><p>SECONDARY / DEFAULT</p><button class="btn secondary" data-action="state-toast">Explore the collection</button></div><div class="component-cell"><p>DISABLED</p><button class="btn" disabled>Unavailable</button></div><div class="component-cell"><p>LOADING / SIMULATED</p><button class="btn" disabled aria-busy="true"><span class="spinner"></span>Adding to bag</button></div><div class="component-cell"><p>SELECTED / UNAVAILABLE</p><div class="size-grid"><button class="size-button" aria-pressed="true" data-action="state-toast">M</button><button class="size-button" aria-pressed="false" data-action="state-toast">L</button><button class="size-button" disabled>XL</button></div></div><div class="component-cell"><p>KEYBOARD FOCUS</p><button class="btn secondary" style="outline:2px solid var(--accent);outline-offset:5px" data-action="state-toast">Visible focus indicator</button></div></div></div><div class="guide-panel"><h2>04 / Feedback & inputs</h2><div class="component-board"><div class="component-cell"><p>INPUT / DEFAULT</p><div class="field"><label for="example-email">Email address</label><input id="example-email" type="email" placeholder="you@example.com"></div></div><div class="component-cell"><p>INPUT / ERROR</p><div class="field"><label for="example-error">Email address</label><input id="example-error" value="name@" aria-invalid="true" aria-describedby="example-error-note"><span class="form-error" id="example-error-note">Enter a valid email address.</span></div></div><div class="component-cell"><p>SUCCESS</p><div class="state-message success">Demo request complete. No information was sent or saved.</div></div><div class="component-cell"><p>ERROR / RECOVERY</p><div class="state-message error">Demo payment declined. Your bag and details are still here.</div></div><div class="component-cell"><p>LOADING / SKELETON</p><div class="skeleton media"></div><div class="skeleton"></div><div class="skeleton short"></div></div><div class="component-cell"><p>EMPTY / RECOVERY</p><h3 style="font-size:23px;margin-bottom:12px">No results.</h3><a class="text-link" href="#/shop">Clear filters ${icon('arrow',16)}</a></div></div></div><div class="guide-panel"><h2>05 / Rhythm & behaviour</h2><div class="spacing-scale">${[4,8,12,16,24,32,48,64,80].map(s=>`<div class="spacing-sample"><div style="height:${s}px"></div><span>${s}px</span></div>`).join('')}</div><div class="guide-columns" style="margin-top:35px"><div><h3>Responsive layout</h3><p>Reference widths: 1440px desktop and 390px mobile. Desktop: 48px margins and four product columns. Mobile: 20px margins and two columns. Breakpoints at 1100px, 760px and 360px. Use fluid sizes, not fixed device heights.</p></div><div><h3>Interaction rules</h3><p>160ms control transitions, 240ms panels and no scroll hijacking. Reduced motion disables animated transitions. Modal dialogs use native focus containment. Core actions remain available without hover.</p></div></div></div></section>`;}
  function notFound(){return `<section class="wrap">${empty('A different direction.','That page is not part of this prototype. The collection is a good place to start.','Explore the collection','#/shop','search')}</section>`;}
  function render(options={}){
    const r=route();
    if(state.modal)closeModal();
    document.body.classList.toggle('product-route',r.path.startsWith('/product/'));
    header();footer(r.path==='/checkout'||r.path==='/confirmation');
    let html;
    if(r.path==='/')html=home();else if(r.path==='/shop')html=shop();else if(r.path.startsWith('/product/'))html=pdp();else if(r.path==='/bag')html=bag();else if(r.path==='/checkout')html=checkout();else if(r.path==='/confirmation')html=confirmation();else if(r.path==='/about')html=about();else if(r.path==='/lookbook')html=lookbook();else if(r.path==='/guide')html=guide();else if(r.path==='/design-system')html=designSystem();else if(r.path.startsWith('/support/'))html=support();else html=notFound();
    $('#main').innerHTML=html;
    document.title=($('#main h1')?.innerText.replace(/\s+/g,' ').trim()||'Built different.')+' | VEXA';
    if(!options.keepScroll){window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});}
    if(r.path.startsWith('/product/'))bindSwipe();
  }
  function openModal(type,body,drawer=false){
    const d=$('#overlay');
    if(!d.open)state.returnFocus=document.activeElement;
    state.modal=type;d.className=drawer?'drawer':'';d.innerHTML=body;document.body.classList.add('modal-open');
    if(!d.open)d.showModal();
    const focus=$('[autofocus]',d)||$('button',d);focus?.focus({preventScroll:true});
  }
  function closeModal(){const d=$('#overlay');if(d.open)d.close();state.modal='';document.body.classList.remove('modal-open');}
  function modalHead(title){return `<div class="dialog-header"><h2 id="dialog-title">${title}</h2><button class="icon-button" data-action="close-modal" aria-label="Close dialog">${icon('close',22)}</button></div>`;}
  function showBag(added=false){openModal('bag',`<div class="drawer-content">${modalHead('Your bag ('+bagCount()+')')}${added?`<div class="drawer-notice">${icon('check',16)} Added to your demo bag</div>`:''}<div class="drawer-scroll">${state.bag.length?state.bag.map((l,i)=>bagLine(l,i,true)).join(''):empty('Your next uniform.','Your bag is empty. Explore the collection to get started.','Shop the collection')}</div>${state.bag.length?`<div class="drawer-footer"><div class="drawer-summary"><span>Subtotal</span><span>${money(subtotal())}</span></div><p class="muted">Sample delivery calculated at checkout. Illustrative prices.</p><a class="btn full" href="#/checkout" data-action="close-link">Checkout ${icon('arrow',17)}</a><a class="btn full secondary" href="#/bag" data-action="close-link">View bag</a></div>`:''}</div>`,true);}
  function showSearch(){openModal('search',`${modalHead('Find your form.')}<div class="dialog-body"><form id="search-form"><label class="sr-only" for="search-input">Search products</label><div class="search-field">${icon('search',22)}<input id="search-input" type="search" name="q" placeholder="Search the collection" maxlength="100" autocomplete="off" autofocus><button type="submit" aria-label="Search">${icon('arrow',22)}</button></div></form><div id="search-preview" class="search-suggestions" aria-live="polite">${searchPreview('')}</div></div>`);}
  function searchPreview(q){const list=q.trim()?D.products.filter(p=>(p.name+' '+p.category+' '+p.collection).toLowerCase().includes(q.trim().toLowerCase())).slice(0,4):D.products.slice(0,3);return `<p class="eyebrow muted">${q.trim()?'MATCHING STYLES':'START WITH THE ESSENTIALS'}</p>${list.length?list.map(p=>`<a class="suggestion-row" href="#/product/${p.id}" data-action="close-link"><img src="${asset(p.image)}" alt=""><span><strong>${p.name}</strong><small>${p.category}</small></span><small>${money(p.price)}</small>${icon('arrow',16)}</a>`).join(''):'<p class="muted" style="padding:20px 0">No matches. Try “hoodie”, “cargo” or “foundation”.</p>'}`;}
  function showFilters(){const p=route().params;openModal('filters',`<div class="drawer-content">${modalHead('Refine the edit.')}<form id="filter-form" class="drawer-content" style="min-height:0;flex:1"><div class="drawer-scroll"><div class="filter-group"><h3>Category</h3>${['All','T-Shirts','Hoodies','Trousers','Outerwear','Accessories'].map(c=>`<label class="check-row"><input type="radio" name="category" value="${c==='All'?'':c}" ${(p.get('category')||'All')===c?'checked':''}>${c}</label>`).join('')}</div><div class="filter-group"><h3>Size</h3><select aria-label="Filter by size" name="size" style="padding:12px;background:transparent;border:1px solid var(--line);width:100%">${['','XS','S','M','L','XL','28','30','32','34','36','One size'].map(s=>`<option value="${s}" ${p.get('size')===s?'selected':''}>${s||'All sizes'}</option>`).join('')}</select></div><div class="filter-group"><h3>Colour</h3>${['All','Washed black','Charcoal','Chalk'].map(c=>`<label class="check-row"><input type="radio" name="colour" value="${c==='All'?'':c}" ${(p.get('colour')||'All')===c?'checked':''}>${c}</label>`).join('')}</div><div class="filter-group"><h3>Price</h3><label class="range-field" for="max-price">Up to £ <input id="max-price" type="number" min="0" max="100000" step="1" name="max" value="${esc(p.get('max')||'')}" placeholder="Any"></label></div><div class="filter-group"><h3>Availability</h3><label class="check-row"><input type="checkbox" name="available" value="1" ${p.get('available')?'checked':''}>Available styles only (demo)</label></div></div><div class="drawer-footer"><button class="btn full" type="submit">Show results ${icon('arrow',17)}</button><button class="btn full secondary" type="button" data-action="reset-filter-form">Reset filters</button></div></form></div>`,true);}
  function showSizeGuide(){const p=product(state.guideProductId||state.pid)||D.products[0],trousers=p.category==='Trousers';openModal('size',`${modalHead('Find your fit.')}<div class="dialog-body"><p class="eyebrow muted">${p.name.toUpperCase()} / SAMPLE MEASUREMENTS</p><p class="fit-instruction" style="margin-top:14px">Garment measurements, laid flat. These are fictional values for testing the interface, not validated sizing advice.</p><div class="measure-toggle" aria-label="Measurement units"><button data-action="unit" data-unit="cm" class="${state.unit==='cm'?'active':''}" aria-pressed="${state.unit==='cm'}">Centimetres</button><button data-action="unit" data-unit="in" class="${state.unit==='in'?'active':''}" aria-pressed="${state.unit==='in'}">Inches</button></div><table class="size-table"><caption>Illustrative ${trousers?'waist, inseam and rise':'chest width, body length and sleeve'} (${state.unit}).</caption><thead><tr><th scope="col">Size</th><th scope="col">${trousers?'Waist':'Chest'}</th><th scope="col">${trousers?'Inseam':'Length'}</th><th scope="col">${trousers?'Rise':'Sleeve'}</th></tr></thead><tbody>${p.sizes.map((s,i)=>{const values=trousers?[71+i*5,78+i,29+i]:[56+i*3,65+i*2,59+i];return `<tr><th scope="row">${s}</th>${values.map(v=>`<td>${state.unit==='cm'?v:(v/2.54).toFixed(1)}</td>`).join('')}</tr>`;}).join('')}</tbody></table><p class="fit-instruction">${p.fit}<br>Production handoff: replace with a product-specific, approved measurement chart.</p></div>`);}
  function addToBag(){
    const p=product(state.pid);if(!p||state.busy||!totalStock(p))return;
    if(!p.sizes.includes(state.size)||!p.stock[state.size]){const error=$('#product-error');error.textContent='Choose a size before adding this piece to your bag.';$('#size-section')?.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});$('.size-button:not(:disabled)')?.focus({preventScroll:true});return;}
    const existing=state.bag.find(l=>l.id===p.id&&l.colour===state.colour&&l.size===state.size);
    if(existing&&existing.qty>=p.stock[state.size]){notify('You have reached the sample quantity limit for this size.');return;}
    state.busy=true;const choice={id:p.id,colour:state.colour,size:state.size,qty:1};
    $$('[data-action="add"]').forEach(b=>{b.disabled=true;b.setAttribute('aria-busy','true');b.innerHTML='<span class="spinner"></span> Adding to bag';});
    setTimeout(()=>{
      const row=state.bag.find(l=>l.id===choice.id&&l.colour===choice.colour&&l.size===choice.size);if(row)row.qty++;else state.bag.push(choice);
      state.bag=cleanBag(state.bag);saveBag();state.busy=false;header();
      $$('[data-action="add"]').forEach(b=>{b.disabled=false;b.removeAttribute('aria-busy');b.innerHTML='Add to bag '+icon('plus',17);});showBag(true);
    },420);
  }
  function updateBag(action,index,delta=0){
    const row=state.bag[index];if(!row)return;
    const oldScroll=window.scrollY;const modalScroll=$('.drawer-scroll')?.scrollTop||0;
    if(action==='remove')state.bag.splice(index,1);else row.qty=Math.min(product(row.id).stock[row.size],Math.max(1,row.qty+delta));
    saveBag();header();
    if(state.modal==='bag'){showBag();$('.drawer-scroll')?.scrollTo(0,modalScroll);}else{render({keepScroll:true});window.scrollTo(0,oldScroll);}
    notify(action==='remove'?'Removed from your bag.':'Bag quantity updated.');
  }
  function captureDetails(){const f=$('#checkout-details');if(!f)return;for(const k of Object.keys(state.details)){const el=f.elements.namedItem(k);if(el)state.details[k]=el.value;}}
  function validateDetails(){captureDetails();let first=null;for(const k of ['email','firstName','lastName','address','city','postal']){const el=$('#'+k);let msg='';if(!el.value.trim())msg='Enter '+({email:'an email address',firstName:'your first name',lastName:'your last name',address:'an address',city:'a city',postal:'a postcode or ZIP'}[k])+'.';else if(k==='email'&&!el.validity.valid)msg='Enter a valid email address.';$('#'+k+'-error').textContent=msg;el.setAttribute('aria-invalid',String(Boolean(msg)));if(msg&&!first)first=el;}if(first){first.focus();return false;}return true;}
  function simulatePayment(){
    if(state.busy)return;
    if(!state.checkoutValid||!state.bag.length){state.checkoutStep=1;render();return;}
    state.busy=true;const btn=$('#payment-button');btn.disabled=true;btn.setAttribute('aria-busy','true');btn.innerHTML='<span class="spinner"></span> Simulating payment';
    setTimeout(()=>{
      state.busy=false;
      if(state.payment==='declined'){
        const e=$('#payment-error');if(!e)return;e.hidden=false;e.className='payment-error';e.textContent='Demo payment declined. Your bag and details are unchanged. Choose “Simulate successful payment” and try again.';btn.disabled=false;btn.removeAttribute('aria-busy');btn.innerHTML='Try demo payment again '+icon('arrow',17);e.scrollIntoView({block:'nearest'});btn.focus({preventScroll:true});return;
      }
      const sub=subtotal(),shipping=shippingChoice();
      state.order={ref:'DEMO-VX-'+String(Date.now()).slice(-6),date:new Date().toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}),lines:state.bag.map(l=>({...l})),subtotal:sub,shippingPrice:shipping.price,shippingName:shipping.name,total:sub+shipping.price};
      state.bag=[];saveBag();state.checkoutStep=1;state.checkoutValid=false;
      state.details={email:'',firstName:'',lastName:'',address:'',apartment:'',city:'',postal:'',country:'United Kingdom'};
      go('/confirmation');
    },650);
  }
  function bindSwipe(){const g=$('.gallery-main');if(!g)return;let start=null,moved=false;g.addEventListener('touchstart',e=>{start=e.touches[0].clientX;moved=false;},{passive:true});g.addEventListener('touchend',e=>{if(start===null)return;const dx=e.changedTouches[0].clientX-start;if(Math.abs(dx)>45){moved=true;state.view=(state.view+(dx<0?1:2))%3;render({keepScroll:true});}start=null;},{passive:true});g.addEventListener('click',e=>{if(moved){e.preventDefault();e.stopPropagation();moved=false;}},true);}
  document.addEventListener('click',e=>{
    const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;
    if(b.disabled)return;
    if(a==='close-link'){closeModal();return;}
    if(a==='close-modal'){closeModal();return;}
    if(a==='bag'){showBag();return;}
    if(a==='search'){showSearch();return;}
    if(a==='menu'){openModal('menu',`<div class="drawer-content">${modalHead('VEXA')}<nav class="menu-links" aria-label="Mobile navigation"><a href="#/shop" data-action="close-link">Shop all</a><a href="#/shop?new=1" data-action="close-link">New arrivals</a><a href="#/lookbook" data-action="close-link">Collections</a><a href="#/about" data-action="close-link">About VEXA</a></nav><div class="menu-bottom"><button class="text-link" data-action="search">Search ${icon('search',18)}</button><p class="eyebrow muted" style="margin-top:25px">CULTURE. FORM. PERSPECTIVE.</p></div></div>`,true);return;}
    if(a==='account'){openModal('account',`${modalHead('A simpler checkout.')}<div class="dialog-body"><h3 style="font-size:27px;margin:5px 0 20px">No account required.</h3><p class="muted" style="font-size:13px;line-height:1.8">This prototype uses guest checkout. Sign-in, saved addresses and order history require a production account service and are not simulated as working authentication.</p><a class="btn full" style="margin-top:25px" href="#/bag" data-action="close-link">Continue as a guest ${icon('arrow',17)}</a></div>`);return;}
    if(a==='quick-view'){go('/product/'+b.dataset.id);return;}
    if(a==='filters'){showFilters();return;}
    if(a==='reset-filter-form'){const f=$('#filter-form');f.reset();f.elements.category.value='';f.elements.colour.value='';f.elements.size.value='';f.elements.max.value='';f.elements.available.checked=false;return;}
    if(a==='clear-all'){go('/shop');return;}
    if(a==='clear-filter'){const p=route().params;p.delete(b.dataset.key);go('/shop'+(p.size?'?'+p.toString():''));return;}
    if(a==='colour'){const old=window.scrollY;state.colour=b.dataset.colour;render({keepScroll:true});window.scrollTo(0,old);$(`.swatch-button[data-colour="${CSS.escape(state.colour)}"]`)?.focus({preventScroll:true});return;}
    if(a==='size'){state.size=b.dataset.size;$$('.size-button[data-action="size"]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.size===state.size)));$('#size-selected-label').textContent='/ '+state.size;$('#mobile-size-label').textContent='Size '+state.size;$('#product-error').textContent='';return;}
    if(a==='gallery'){state.view=Number(b.dataset.view);const g=$('.gallery-main');g.dataset.view=String(state.view);$('.photo-label',g).textContent=['01 / FRONT VIEW','02 / DETAIL CROP','03 / CONSTRUCTION CROP'][state.view];$('#main-product-image').alt=product(state.pid).name+', illustrative '+['front view','detail crop','construction crop'][state.view];$$('.gallery-thumb').forEach(x=>{x.classList.toggle('active',Number(x.dataset.view)===state.view);x.setAttribute('aria-pressed',String(Number(x.dataset.view)===state.view));});return;}
    if(a==='zoom'){const p=product(state.pid),c=p.colours.find(c=>c.name===state.colour);openModal('zoom',`${modalHead(p.name)}<div class="zoom-body"><img class="zoom-image" src="${asset(c.image)}" alt="${p.name}, enlarged illustrative front view"><p class="asset-note" style="padding:10px">Enlarged concept image. The source asset is low resolution; this is not additional product detail.</p></div>`);return;}
    if(a==='size-guide'||a==='general-size-guide'){state.guideProductId=a==='general-size-guide'?'foundation-hoodie':state.pid;showSizeGuide();return;}
    if(a==='unit'){state.unit=b.dataset.unit;showSizeGuide();return;}
    if(a==='add'){addToBag();return;}
    if(a==='qty'||a==='remove'){updateBag(a,Number(b.dataset.index),Number(b.dataset.delta)||0);return;}
    if(a==='checkout-step'){captureDetails();const next=Number(b.dataset.step);if(next>1&&!state.checkoutValid)return;state.checkoutStep=next;render();return;}
    if(a==='sample-details'){state.details={email:'jamie@example.com',firstName:'Jamie',lastName:'Morgan',address:'12 Example Street',apartment:'',city:'London',postal:'DEMO 1AA',country:'United Kingdom'};render({keepScroll:true});notify('Sample details filled. No real address or email is needed.');return;}
    if(a==='seed-bag'){state.bag=[{id:'foundation-hoodie',size:'M',colour:'Washed black',qty:1},{id:'tactical-cargo',size:'32',colour:'Charcoal',qty:1}];saveBag();go('/bag');notify('Sample bag loaded: two items.');return;}
    if(a==='notify-stock'){openModal('notify',`${modalHead('Keep this on your radar.')}<div class="dialog-body"><p class="muted" style="line-height:1.8">Preview an availability request. No request or email will be sent, and no information will be saved.</p><form id="stock-form" style="margin-top:23px" novalidate><div class="field"><label for="stock-email">Email address</label><input id="stock-email" type="email" name="email" required aria-describedby="stock-error"><span id="stock-error" class="form-error"></span></div><button class="btn full" style="margin-top:20px" type="submit">Preview request</button></form></div>`);return;}
    if(a==='sample-enquiry'){notify('Demo enquiry complete. Nothing was submitted.');return;}
    if(a==='state-toast'){notify('Component preview. Use the shop to test the connected journey.');return;}
  });
  document.addEventListener('input',e=>{
    if(e.target.id==='search-input')$('#search-preview').innerHTML=searchPreview(e.target.value);
    if(e.target.closest('#checkout-details')){captureDetails();state.checkoutValid=false;if(e.target.id&&$('#'+e.target.id+'-error')){$('#'+e.target.id+'-error').textContent='';e.target.removeAttribute('aria-invalid');}}
  });
  document.addEventListener('change',e=>{
    if(e.target.id==='sort'){const p=route().params;e.target.value==='featured'?p.delete('sort'):p.set('sort',e.target.value);go('/shop'+(p.size?'?'+p.toString():''));}
    if(e.target.name==='shipping'){state.shipping=e.target.value;const summary=$('.order-summary');if(summary)summary.outerHTML=orderSummary(true);}
    if(e.target.name==='payment')state.payment=e.target.value;
    if(e.target.name==='country')captureDetails();
  });
  document.addEventListener('submit',e=>{
    const f=e.target;
    if(f.id==='search-form'){e.preventDefault();const q=f.elements.q.value.trim();closeModal();go('/shop'+(q?'?q='+encodeURIComponent(q):''));}
    if(f.id==='filter-form'){e.preventDefault();const p=route().params;['category','colour','size','max','available','empty'].forEach(k=>p.delete(k));const form=new FormData(f);for(const k of ['category','colour','size','max','available']){const v=form.get(k);if(v!==null&&v!=='')p.set(k,v);}closeModal();go('/shop'+(p.size?'?'+p.toString():''));}
    if(f.id==='checkout-details'){e.preventDefault();if(validateDetails()){state.checkoutValid=true;state.checkoutStep=2;render();}}
    if(f.id==='shipping-form'){e.preventDefault();state.shipping=f.elements.shipping.value;state.checkoutStep=3;render();}
    if(f.id==='payment-form'){e.preventDefault();state.payment=f.elements.payment.value;simulatePayment();}
    if(f.id==='newsletter-form'){e.preventDefault();const input=f.elements.email,note=$('#newsletter-note');if(!input.validity.valid){note.textContent='Enter a valid email address to preview sign-up.';note.style.color='var(--error)';input.setAttribute('aria-invalid','true');input.focus();}else{note.textContent='Demo sign-up complete. Nothing was sent or saved.';note.style.color='var(--success)';input.removeAttribute('aria-invalid');input.value='';notify('Newsletter success state previewed. No subscription created.');}}
    if(f.id==='stock-form'){e.preventDefault();const input=f.elements.email;if(!input.validity.valid){$('#stock-error').textContent='Enter a valid email address.';input.setAttribute('aria-invalid','true');input.focus();}else{closeModal();notify('Demo availability request complete. Nothing was sent or saved.');}}
  });
  $('#overlay').addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();closeModal();}});
  $('#overlay').addEventListener('close',()=>{document.body.classList.remove('modal-open');state.modal='';if(state.returnFocus?.isConnected)state.returnFocus.focus({preventScroll:true});});
  $('#overlay').addEventListener('click',e=>{if(e.target!==e.currentTarget)return;const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();});
  window.addEventListener('hashchange',()=>{if(!location.hash.startsWith('#/'))return;render();});
  window.addEventListener('storage',e=>{if(e.key===storageKey){state.bag=loadBag();header();if(route().path==='/bag'||route().path==='/checkout')render({keepScroll:true});}});
  render();
})();
